def flatten(obj, sep='.') -> dict:
    _NO_PREFIX = object()

    def _walk(value, prefix):
        if isinstance(value, dict):
            for key, val in value.items():
                new_prefix = key if prefix is _NO_PREFIX else f"{prefix}{sep}{key}"
                yield from _walk(val, new_prefix)
        elif isinstance(value, list):
            for idx, val in enumerate(value):
                new_prefix = idx if prefix is _NO_PREFIX else f"{prefix}{sep}{idx}"
                yield from _walk(val, new_prefix)
        else:
            yield (0 if prefix is _NO_PREFIX else prefix), value

    return dict(_walk(obj, _NO_PREFIX))

def flatten(obj, sep='.') -> dict:
    result = {}

    def _flatten(value, prefix):
        if isinstance(value, dict):
            for k, v in value.items():
                key = str(k)
                new_prefix = key if prefix is None else f"{prefix}{sep}{key}"
                _flatten(v, new_prefix)
        elif isinstance(value, list):
            for i, v in enumerate(value):
                key = str(i)
                new_prefix = key if prefix is None else f"{prefix}{sep}{key}"
                _flatten(v, new_prefix)
        else:
            if prefix is None:
                result["0"] = value
            else:
                result[prefix] = value

    _flatten(obj, None)
    return result

