def retry(times: int, exceptions=(Exception,)):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            if times <= 0:
                return func(*args, **kwargs)

            last_exc = None
            for _ in range(times):
                try:
                    return func(*args, **kwargs)
                except exceptions as exc:
                    last_exc = exc

            raise last_exc

        return wrapper

    return decorator

