import re


def parse_select(sql: str) -> dict:
    sql = sql.strip().rstrip(";").strip()

    pattern = re.compile(
        r"^\s*SELECT\s+(?P<columns>.+?)\s+FROM\s+(?P<table>\S+)"
        r"(?:\s+WHERE\s+(?P<where>.+?))?\s*$",
        re.IGNORECASE | re.DOTALL,
    )

    match = pattern.match(sql)
    if match is None:
        raise ValueError("Invalid SELECT statement")

    raw_columns = match.group("columns").strip()
    if raw_columns == "*":
        columns = ["*"]
    else:
        columns = [col.strip() for col in raw_columns.split(",")]

    table = match.group("table").strip()
    where = match.group("where")
    if where is not None:
        where = where.strip()

    return {
        "columns": columns,
        "table": table,
        "where": where,
    }

import heapq


def topo_sort(nodes: list, edges: list[tuple]) -> list:
    graph = {node: [] for node in nodes}
    indegree = {node: 0 for node in nodes}

    for a, b in edges:
        if a not in graph:
            graph[a] = []
            indegree[a] = 0
        if b not in graph:
            graph[b] = []
            indegree[b] = 0

        graph[a].append(b)
        indegree[b] += 1

    heap = [node for node, degree in indegree.items() if degree == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)

        for neighbor in graph[node]:
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                heapq.heappush(heap, neighbor)

    if len(result) != len(graph):
        raise ValueError("Cycle detected")

    return result

