from heapq import heapify, heappop, heappush


def topo_sort(nodes: list, edges: list[tuple]) -> list:
    sorted_nodes = sorted(nodes)
    unique_nodes = []
    for node in sorted_nodes:
        if not unique_nodes or node != unique_nodes[-1]:
            unique_nodes.append(node)

    n = len(unique_nodes)
    indegree = [0] * n
    adjacency = [[] for _ in range(n)]

    def find_index(value):
        try:
            i = bisect_left(unique_nodes, value)
        except TypeError:
            for i, node in enumerate(unique_nodes):
                if node == value:
                    return i
            return -1

        if i < n and unique_nodes[i] == value:
            return i
        return -1

    for a, b in edges:
        ia = find_index(a)
        ib = find_index(b)
        if ia != -1 and ib != -1:
            adjacency[ia].append(ib)
            indegree[ib] += 1

    heap = [i for i in range(n) if indegree[i] == 0]
    heapify(heap)

    result = []
    while heap:
        i = heappop(heap)
        result.append(unique_nodes[i])
        for j in adjacency[i]:
            indegree[j] -= 1
            if indegree[j] == 0:
                heappush(heap, j)

    if len(result) != n:
        raise ValueError("Cycle detected")

    return result

