import string


def ladder_length(begin: str, end: str, words: list[str]) -> int:
    word_set = set(words)

    if end not in word_set or len(begin) != len(end):
        return 0

    if begin == end:
        return 1

    if begin in word_set:
        word_set.remove(begin)

    queue = deque([begin])
    length = 1
    letters = string.ascii_lowercase
    n = len(begin)

    while queue:
        for _ in range(len(queue)):
            word = queue.popleft()

            for i in range(n):
                for ch in letters:
                    if ch == word[i]:
                        continue

                    next_word = word[:i] + ch + word[i + 1:]

                    if next_word in word_set:
                        if next_word == end:
                            return length + 1

                        word_set.remove(next_word)
                        queue.append(next_word)

        length += 1

    return 0

from collections import deque

def ladder_length(begin: str, end: str, words: list[str]) -> int:
    if begin == end:
        return 1

    word_set = set(words)
    if end not in word_set:
        return 0

    length = len(begin)
    if len(end) != length:
        return 0

    patterns = {}
    for word in word_set:
        if len(word) != length:
            continue
        for i in range(length):
            key = (word[:i], word[i + 1:])
            patterns.setdefault(key, []).append(word)

    visited = {begin}
    queue = deque([(begin, 1)])

    while queue:
        word, depth = queue.popleft()

        for i in range(length):
            key = (word[:i], word[i + 1:])
            for neighbor in patterns.get(key, ()):
                if neighbor in visited:
                    continue
                if neighbor == end:
                    return depth + 1

                visited.add(neighbor)
                queue.append((neighbor, depth + 1))

    return 0

def diff(a: list[str], b: list[str]) -> list[tuple[str, str]]:
    if not a:
        return [('+', line) for line in b]
    if not b:
        return [('-', line) for line in a]
    if a == b:
        return [(' ', line) for line in a]

    n, m = len(a), len(b)
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    for i in range(n - 1, -1, -1):
        ai = a[i]
        row = dp[i]
        next_row = dp[i + 1]
        for j in range(m - 1, -1, -1):
            if ai == b[j]:
                row[j] = next_row[j + 1] + 1
            else:
                row[j] = next_row[j] if next_row[j] >= row[j + 1] else row[j + 1]

    lcs = []
    i = j = 0
    while i < n and j < m:
        if a[i] == b[j]:
            lcs.append((i, j))
            i += 1
            j += 1
        elif dp[i + 1][j] >= dp[i][j + 1]:
            i += 1
        else:
            j += 1

    result: list[tuple[str, str]] = []
    pi = pj = 0

    for i, j in lcs:
        for k in range(pi, i):
            result.append(('-', a[k]))
        for k in range(pj, j):
            result.append(('+', b[k]))
        result.append((' ', a[i]))
        pi, pj = i + 1, j + 1

    for k in range(pi, n):
        result.append(('-', a[k]))
    for k in range(pj, m):
        result.append(('+', b[k]))

    return result
